            last_row: snapshot.max_point().row,
            buffer_snapshot: snapshot.clone(),
            max_rows_per_chunk,
            computed_chunks: Mutex::new(HashMap::default()),
        }
    }

    pub fn version(&self) -> &clock::Global {
        self.buffer_snapshot.version()
