			'file',
			'vscode-notebook-cell',
			'untitled',
			// "vscode-local",
			// "vscode-chat-code-block",
			// "chat-editing-text-model",
			// "embedded-html",
			// "vscode-userdata",
			// "vscode-remote",
			// "git",
